insert into public.domain_assignments (node_id, domain_id, source, confidence, pinned, assigned_by, assigned_at) values ('PY01', 'python-engineering', 'admin', null, true, 'global-admin-demo', '2026-08-08T00:00:00.000Z');
insert into public.workflow_templates (id, name, description, definition) values ('support-ticket-showcase', '客服工单处理闭环', '模拟售后客服工单：清洗输入、读取附件、查询客户资料、按问题类型分流，并通过 Agent + Tool 循环生成可归档回复。', '{"id":"support-ticket-showcase","name":"客服工单处理闭环","description":"模拟售后客服工单：清洗输入、读取附件、查询客户资料、按问题类型分流，并通过 Agent + Tool 循环生成可归档回复。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":20,"y":300,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"clean_ticket","label":"清洗工单","subtitle":"Function Node","kind":"function","x":170,"y":300,"reads":["user_input"],"writes":["query","messages","iteration"],"logic":"提取用户诉求、订单线索和联系方式，初始化消息历史与循环次数。","code":"def clean_ticket(state: State):\n    text = state[\"user_input\"].strip()\n    return {\n        \"query\": text,\n        \"messages\": [{\"role\": \"user\", \"content\": text}],\n        \"iteration\": 0\n    }"},{"id":"read_attachment","label":"读取附件","subtitle":"File / Cloud Drive Node","kind":"file","x":350,"y":170,"reads":["query"],"writes":["draft_answer"],"logic":"读取用户上传的截图、发票或日志摘要，作为后续判断的上下文。","code":"def read_attachment(state: State):\n    return {\n        \"draft_answer\": \"附件摘要：包含订单号、付款截图和用户描述的问题现象。\"\n    }"},{"id":"query_customer","label":"查询客户资料","subtitle":"Database Node","kind":"database","x":350,"y":430,"reads":["query"],"writes":["api_result"],"logic":"根据工单线索查询客户等级、订单状态、历史售后记录。","code":"def query_customer(state: State):\n    return {\n        \"api_result\": {\n            \"customer_tier\": \"gold\",\n            \"order_status\": \"paid\",\n            \"last_ticket\": \"none\"\n        }\n    }"},{"id":"classify_ticket","label":"分类工单","subtitle":"Function Node","kind":"function","x":540,"y":300,"reads":["query","draft_answer","api_result"],"writes":["task_type"],"logic":"根据用户诉求与客户资料判断 refund / technical / account / human_review。","code":"def classify_ticket(state: State):\n    text = state[\"query\"]\n    if \"退款\" in text or \"退货\" in text:\n        task_type = \"refund\"\n    elif \"登录\" in text or \"账号\" in text:\n        task_type = \"account\"\n    elif \"报错\" in text or \"无法使用\" in text:\n        task_type = \"technical\"\n    else:\n        task_type = \"human_review\"\n    return {\"task_type\": task_type}"},{"id":"ticket_router","label":"工单路由","subtitle":"Router Node","kind":"router","x":735,"y":300,"reads":["task_type"],"writes":[],"logic":"读取 task_type，将工单分发到退款、技术、账号或人工复核路径。","control":{"branches":["refund","technical","account","human_review"]}},{"id":"search_policy","label":"检索知识库","subtitle":"HTTP API Node","kind":"http","x":960,"y":135,"reads":["query","task_type"],"writes":["api_result","draft_answer"],"logic":"调用知识库检索售后政策、处理话术和故障排查步骤。","code":"def search_policy(state: State):\n    return {\n        \"api_result\": {\"policy\": \"符合条件可优先补偿或退款\"},\n        \"draft_answer\": \"知识库建议：先核验订单，再给出可执行处理方案。\"\n    }"},{"id":"draft_reply","label":"生成回复草稿","subtitle":"LLM Node","kind":"llm","x":960,"y":300,"reads":["query","api_result","draft_answer"],"writes":["draft_answer"],"logic":"结合客户资料、附件摘要和知识库结果生成客服回复草稿。","code":"def draft_reply(state: State):\n    return {\n        \"draft_answer\": \"您好，我们已核验订单和问题描述，将按售后政策为您处理。\"\n    }"},{"id":"support_agent","label":"客服 Agent","subtitle":"Agent Node","kind":"agent","x":1170,"y":300,"reads":["messages","query","draft_answer","tool_result","iteration"],"writes":["messages","should_continue","tool_name","tool_args","iteration","draft_answer"],"logic":"判断是否还需要查询订单、物流或优惠券状态；拿到工具结果后决定是否结束。","code":"def support_agent(state: State):\n    iteration = state.get(\"iteration\", 0)\n    should_continue = iteration < 1\n    return {\n        \"messages\": state[\"messages\"] + [{\"role\": \"assistant\", \"content\": \"需要补充订单状态。\" if should_continue else \"信息已完整，可以回复。\"}],\n        \"should_continue\": should_continue,\n        \"tool_name\": \"order_status\" if should_continue else None,\n        \"tool_args\": {\"query\": state[\"query\"]} if should_continue else None,\n        \"iteration\": iteration + 1,\n        \"draft_answer\": state.get(\"draft_answer\", \"\")\n    }"},{"id":"agent_loop","label":"复核循环","subtitle":"Loop Node","kind":"loop","x":1390,"y":300,"reads":["should_continue"],"writes":[],"logic":"根据 should_continue 控制 Agent 是否继续调用工具。","control":{"branches":["continue","end"]}},{"id":"order_tool","label":"订单工具","subtitle":"Tool Node","kind":"tool","x":1390,"y":515,"reads":["tool_name","tool_args","messages"],"writes":["tool_result","messages"],"logic":"调用内部订单、物流或优惠券工具，并把结果写回消息历史。","code":"def order_tool(state: State):\n    result = \"订单状态：已付款，物流未发出，可走优先退款。\"\n    return {\n        \"tool_result\": result,\n        \"messages\": state[\"messages\"] + [{\"role\": \"tool\", \"content\": result}]\n    }"},{"id":"format_reply","label":"格式化回复","subtitle":"State Transform Node","kind":"transform","x":1610,"y":300,"reads":["draft_answer","tool_result","task_type"],"writes":["final_answer"],"logic":"将草稿、工具结果和工单分类整理成可发送的标准客服回复。","code":"def format_reply(state: State):\n    return {\n        \"final_answer\": f\"处理类型：{state[''task_type'']}。回复：{state[''draft_answer'']} {state.get(''tool_result'') or ''''}\"\n    }"},{"id":"archive_ticket","label":"归档工单","subtitle":"Output Node","kind":"output","x":1810,"y":300,"reads":["final_answer"],"writes":["messages"],"logic":"记录最终回复、处理类型和客服操作结果，完成工单闭环。","code":"def archive_ticket(state: State):\n    return {\n        \"messages\": state[\"messages\"] + [{\"role\": \"system\", \"content\": state[\"final_answer\"]}]\n    }"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":2000,"y":300,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-support-start-clean","from":"start","to":"clean_ticket","label":"next","kind":"normal"},{"id":"e-support-clean-file","from":"clean_ticket","to":"read_attachment","label":"next","kind":"normal"},{"id":"e-support-file-db","from":"read_attachment","to":"query_customer","label":"next","kind":"normal"},{"id":"e-support-db-classify","from":"query_customer","to":"classify_ticket","label":"next","kind":"normal"},{"id":"e-support-classify-router","from":"classify_ticket","to":"ticket_router","label":"next","kind":"normal"},{"id":"e-support-router-refund","from":"ticket_router","to":"search_policy","label":"refund","kind":"normal"},{"id":"e-support-router-technical","from":"ticket_router","to":"search_policy","label":"technical","kind":"normal"},{"id":"e-support-router-account","from":"ticket_router","to":"support_agent","label":"account","kind":"normal"},{"id":"e-support-router-human","from":"ticket_router","to":"format_reply","label":"human_review","kind":"normal"},{"id":"e-support-policy-draft","from":"search_policy","to":"draft_reply","label":"next","kind":"normal"},{"id":"e-support-draft-agent","from":"draft_reply","to":"support_agent","label":"next","kind":"normal"},{"id":"e-support-agent-loop","from":"support_agent","to":"agent_loop","label":"next","kind":"normal"},{"id":"e-support-loop-tool","from":"agent_loop","to":"order_tool","label":"continue","kind":"normal"},{"id":"e-support-tool-agent","from":"order_tool","to":"support_agent","label":"next","kind":"normal"},{"id":"e-support-loop-format","from":"agent_loop","to":"format_reply","label":"end","kind":"normal"},{"id":"e-support-format-output","from":"format_reply","to":"archive_ticket","label":"next","kind":"normal"},{"id":"e-support-output-end","from":"archive_ticket","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-support-start-clean","clean_ticket","e-support-clean-file","read_attachment","e-support-file-db","query_customer","e-support-db-classify","classify_ticket","e-support-classify-router","ticket_router","e-support-router-refund","search_policy","e-support-policy-draft","draft_reply","e-support-draft-agent","support_agent","e-support-agent-loop","agent_loop","e-support-loop-tool","order_tool","e-support-tool-agent","support_agent","e-support-agent-loop","agent_loop","e-support-loop-format","format_reply","e-support-format-output","archive_ticket","e-support-output-end","end"],"result":"final_answer: 处理类型：refund。您好，我们已核验订单和售后政策，可为该订单优先发起退款，并已记录工单处理结果。","code":"查看全部代码会展示客服工单处理的分文件 LangGraph 原型代码。"}');
insert into public.workflow_templates (id, name, description, definition) values ('showcase', '知序 LangGraph 示例', '节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。', '{"id":"showcase","name":"知序 LangGraph 示例","description":"节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":20,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"normalize_input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":250,"reads":["user_input"],"writes":["query","messages","iteration"],"logic":"清理 user_input，初始化 messages 和 iteration。"},{"id":"classify_task","label":"Classify Task","subtitle":"Function Node","kind":"function","x":355,"y":250,"reads":["user_input"],"writes":["task_type"],"logic":"根据用户输入判断 search / writing / agent / end。"},{"id":"task_router","label":"Task Router","subtitle":"Router Node","kind":"router","x":560,"y":250,"reads":["task_type"],"writes":[],"logic":"读取 task_type，将分支映射到后续节点。","control":{"branches":["search","writing","agent","end"]}},{"id":"call_search_api","label":"HTTP API Node","subtitle":"HTTP API Node","kind":"http","x":790,"y":60,"reads":["query"],"writes":["api_result","draft_answer"],"logic":"通过环境变量配置第三方搜索 API。"},{"id":"write_answer","label":"LLM Node","subtitle":"LLM Node","kind":"llm","x":790,"y":200,"reads":["query"],"writes":["draft_answer"],"logic":"调用大模型生成教学回答草稿。"},{"id":"agent","label":"Agent Node","subtitle":"Agent Node","kind":"agent","x":790,"y":360,"reads":["messages","query","tool_result","iteration"],"writes":["messages","should_continue","tool_name","tool_args","iteration","draft_answer"],"logic":"判断是否继续调用工具。"},{"id":"agent_loop","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":1010,"y":360,"reads":["should_continue"],"writes":[],"logic":"读取 should_continue，决定继续调用工具或退出。","control":{"branches":["continue","end"]}},{"id":"tool","label":"Tool Node","subtitle":"Tool Node","kind":"tool","x":1010,"y":520,"reads":["tool_name","tool_args","messages"],"writes":["tool_result","messages"],"logic":"根据 tool_name 调用内部工具。"},{"id":"format_answer","label":"Format Answer","subtitle":"State Transform Node","kind":"transform","x":1190,"y":200,"reads":["draft_answer"],"writes":["final_answer"],"logic":"将 draft_answer 格式化为 final_answer。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1400,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-start-normalize","from":"start","to":"normalize_input","label":"next","kind":"normal"},{"id":"e-normalize-classify","from":"normalize_input","to":"classify_task","label":"next","kind":"normal"},{"id":"e-classify-router","from":"classify_task","to":"task_router","label":"next","kind":"normal"},{"id":"e-router-search","from":"task_router","to":"call_search_api","label":"search","kind":"normal"},{"id":"e-router-writing","from":"task_router","to":"write_answer","label":"writing","kind":"normal"},{"id":"e-router-agent","from":"task_router","to":"agent","label":"agent","kind":"normal"},{"id":"e-router-end","from":"task_router","to":"end","label":"end","kind":"normal"},{"id":"e-api-format","from":"call_search_api","to":"format_answer","label":"next","kind":"normal"},{"id":"e-llm-format","from":"write_answer","to":"format_answer","label":"next","kind":"normal"},{"id":"e-agent-loop","from":"agent","to":"agent_loop","label":"next","kind":"normal"},{"id":"e-loop-continue","from":"agent_loop","to":"tool","label":"continue","kind":"normal"},{"id":"e-tool-agent","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e-loop-end","from":"agent_loop","to":"format_answer","label":"end","kind":"normal"},{"id":"e-format-end","from":"format_answer","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-start-normalize","normalize_input","e-normalize-classify","classify_task","e-classify-router","task_router","e-router-agent","agent","e-agent-loop","agent_loop","e-loop-continue","tool","e-tool-agent","agent","e-agent-loop","agent_loop","e-loop-end","format_answer","e-format-end","end"],"result":"final_answer: 最终回答：Agent 已调用工具并完成回答。","code":"查看全部代码会展示分文件 LangGraph 原型代码。"}');
insert into public.workflow_templates (id, name, description, definition) values ('minimal', '最小工作流', 'START 进入一个处理节点，写入 final_answer 后到 END。', '{"id":"minimal","name":"最小工作流","description":"START 进入一个处理节点，写入 final_answer 后到 END。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":50,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"process","label":"Function Node","subtitle":"Function Node","kind":"function","x":250,"y":180,"reads":["user_input"],"writes":["final_answer"],"logic":"读取 user_input，生成教学演示结果。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":500,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"process","label":"next","kind":"normal"},{"id":"e2","from":"process","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","process","e2","end"],"result":"final_answer: 已根据 user_input 生成一个可解释的处理结果。","code":"class State(TypedDict):\n    user_input: str\n    final_answer: str\n\ndef process_node(state: State):\n    return {\"final_answer\": \"处理完成\"}\n\ngraph = StateGraph(State)\ngraph.add_node(\"process_node\", process_node)\ngraph.add_edge(START, \"process_node\")\ngraph.add_edge(\"process_node\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('sequence', '顺序工作流', '多个节点依次读取并更新共享 State。', '{"id":"sequence","name":"顺序工作流","description":"多个节点依次读取并更新共享 State。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":95,"reads":["user_input"],"writes":["messages"],"logic":"接收测试输入并写入消息历史。"},{"id":"read","label":"File Node","subtitle":"File / Cloud Drive Node","kind":"file","x":345,"y":95,"reads":["user_input"],"writes":["tool_result"],"logic":"模拟读取文件内容。"},{"id":"summary","label":"Summary Node","subtitle":"LLM Node","kind":"llm","x":345,"y":305,"reads":["tool_result"],"writes":["final_answer"],"logic":"读取文件内容并生成摘要。"},{"id":"output","label":"Output Node","subtitle":"基础节点 / 输出","kind":"output","x":510,"y":210,"reads":["final_answer"],"writes":["messages"],"logic":"整理最终输出并追加消息。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":720,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"input","label":"next","kind":"normal"},{"id":"e2","from":"input","to":"read","label":"next","kind":"normal"},{"id":"e3","from":"read","to":"summary","label":"next","kind":"normal"},{"id":"e4","from":"summary","to":"output","label":"next","kind":"normal"},{"id":"e5","from":"output","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","input","e2","read","e3","summary","e4","output","e5","end"],"result":"final_answer: 这份文件已经被读取、摘要并整理为教学输出。","code":"graph.add_node(\"input_node\", input_node)\ngraph.add_node(\"read_file_node\", read_file_node)\ngraph.add_node(\"summary_node\", summary_node)\ngraph.add_node(\"output_node\", output_node)\n\ngraph.add_edge(START, \"input_node\")\ngraph.add_edge(\"input_node\", \"read_file_node\")\ngraph.add_edge(\"read_file_node\", \"summary_node\")\ngraph.add_edge(\"summary_node\", \"output_node\")\ngraph.add_edge(\"output_node\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('branch', '条件分支', 'Function 写入 task_type，Router 节点决定后续路径。', '{"id":"branch","name":"条件分支","description":"Function 写入 task_type，Router 节点决定后续路径。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"classify_task","label":"Classify Task","subtitle":"Function Node","kind":"function","x":170,"y":190,"reads":["user_input"],"writes":["task_type"],"logic":"判断用户意图并写入 task_type。"},{"id":"router","label":"Task Router","subtitle":"Router Node","kind":"router","x":360,"y":190,"reads":["task_type"],"writes":[],"logic":"读取 task_type 并映射分支。","control":{"branches":["writing","search"]}},{"id":"summary","label":"Summary Node","subtitle":"LLM Node","kind":"llm","x":560,"y":90,"reads":["user_input","task_type"],"writes":["draft_answer"],"logic":"当 task_type 为 writing 时执行。"},{"id":"search","label":"HTTP API Node","subtitle":"HTTP API Node","kind":"http","x":560,"y":305,"reads":["query","task_type"],"writes":["draft_answer"],"logic":"当 task_type 为 search 时执行。"},{"id":"merge","label":"Format Answer","subtitle":"State Transform Node","kind":"transform","x":760,"y":190,"reads":["draft_answer"],"writes":["final_answer"],"logic":"合并分支输出。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":720,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"classify_task","label":"next","kind":"normal"},{"id":"e2","from":"classify_task","to":"router","label":"next","kind":"normal"},{"id":"e3","from":"router","to":"summary","label":"writing","kind":"normal"},{"id":"e4","from":"router","to":"search","label":"search","kind":"normal"},{"id":"e5","from":"summary","to":"merge","label":"next","kind":"normal"},{"id":"e6","from":"search","to":"merge","label":"next","kind":"normal"},{"id":"e7","from":"merge","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","router","e2","summary","e4","merge","e6","end"],"result":"final_answer: Router 判定为 summary，流程进入 Summary Node 并完成输出。","code":"def router(state: State):\n    if \"总结\" in state[\"user_input\"]:\n        return \"summary\"\n    if \"改写\" in state[\"user_input\"]:\n        return \"rewrite\"\n    return \"fallback\"\n\ngraph.add_conditional_edges(\n    \"router_node\",\n    router,\n    {\"summary\": \"summary_node\", \"rewrite\": \"rewrite_node\"}\n)"}');
insert into public.workflow_templates (id, name, description, definition) values ('agent', 'Agent 工具调用', 'Agent 根据 should_continue 决定调用 Tool 或结束。', '{"id":"agent","name":"Agent 工具调用","description":"Agent 根据 should_continue 决定调用 Tool 或结束。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"agent","label":"Agent Node","subtitle":"Agent 节点 / Agent","kind":"agent","x":190,"y":185,"reads":["user_input","messages","tool_result"],"writes":["messages","should_continue","tool_name","tool_args","final_answer"],"logic":"判断是否需要工具，最多循环 5 次。"},{"id":"tool","label":"Search Tool","subtitle":"Agent 节点 / Tool","kind":"tool","x":405,"y":310,"reads":["tool_call"],"writes":["tool_result","messages"],"logic":"根据 tool_call.query 模拟搜索并写回 tool_result。"},{"id":"observe","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":405,"y":95,"reads":["should_continue"],"writes":[],"logic":"根据 should_continue 控制循环。","control":{"branches":["continue","end"]}},{"id":"end","label":"END","subtitle":"System","kind":"system","x":700,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"agent","label":"next","kind":"normal"},{"id":"e2","from":"agent","to":"observe","label":"next","kind":"normal"},{"id":"e3","from":"observe","to":"tool","label":"continue","kind":"normal"},{"id":"e4","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e5","from":"observe","to":"end","label":"end","kind":"normal"}],"runOrder":["start","e1","agent","e2","tool","e3","observe","e4","agent","e5","end"],"result":"final_answer: Agent 已调用 Search Tool，吸收 Observation 后满足停止条件并结束。","code":"graph.add_node(\"agent\", agent_node)\ngraph.add_node(\"search_tool\", search_tool)\ngraph.add_node(\"observation\", observation_node)\n\ngraph.add_conditional_edges(\n    \"agent\",\n    route_agent,\n    {\"need_tool\": \"search_tool\", \"done\": END}\n)\ngraph.add_edge(\"search_tool\", \"observation\")\ngraph.add_edge(\"observation\", \"agent\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('lesson-04-direct', 'Direct · 政策简报基线', '一次生成三所高校的生成式 AI 政策比较简报，用作速度、成本、覆盖度和引用可靠性的基线。', '{"id":"lesson-04-direct","name":"Direct · 政策简报基线","description":"一次生成三所高校的生成式 AI 政策比较简报，用作速度、成本、覆盖度和引用可靠性的基线。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":60,"y":240,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"brief_input","label":"研究任务","subtitle":"Input Node","kind":"function","x":220,"y":205,"reads":["user_input"],"writes":["query"],"logic":"接收政策比较任务和 800-1200 字输出约束。"},{"id":"direct_writer","label":"Direct Writer","subtitle":"LLM Node","kind":"llm","x":470,"y":205,"reads":["query"],"writes":["final_answer"],"logic":"不调用外部工具，直接使用模型已有知识生成简报。"},{"id":"constraint_check","label":"约束检查","subtitle":"Function Node","kind":"function","x":720,"y":205,"reads":["final_answer"],"writes":["draft_answer"],"logic":"检查三所高校、风险和三条建议是否出现。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":960,"y":240,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-direct-1","from":"start","to":"brief_input","label":"next","kind":"normal"},{"id":"e-direct-2","from":"brief_input","to":"direct_writer","label":"next","kind":"normal"},{"id":"e-direct-3","from":"direct_writer","to":"constraint_check","label":"next","kind":"normal"},{"id":"e-direct-4","from":"constraint_check","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-direct-1","brief_input","e-direct-2","direct_writer","e-direct-3","constraint_check","e-direct-4","end"],"result":"final_answer: 已生成政策简报基线；覆盖三所高校与三条建议，但没有主动检索，引用可靠性需要人工核验。","code":"graph.add_node(\"direct_writer\", direct_writer)\ngraph.add_node(\"constraint_check\", constraint_check)\ngraph.add_edge(START, \"direct_writer\")\ngraph.add_edge(\"direct_writer\", \"constraint_check\")\ngraph.add_edge(\"constraint_check\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('lesson-04-react', 'ReAct · 搜索与观察循环', '边判断信息缺口、边调用官方来源搜索工具，并依据观察结果决定继续检索或结束。', '{"id":"lesson-04-react","name":"ReAct · 搜索与观察循环","description":"边判断信息缺口、边调用官方来源搜索工具，并依据观察结果决定继续检索或结束。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":260,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"react_agent","label":"ReAct Agent","subtitle":"Agent Node","kind":"agent","x":210,"y":220,"reads":["user_input","messages","tool_result","iteration"],"writes":["messages","tool_name","tool_args","should_continue","iteration","draft_answer"],"logic":"维护当前子目标，选择高校官方政策搜索或结束。"},{"id":"react_route","label":"继续检索？","subtitle":"Loop Node","kind":"loop","x":470,"y":220,"reads":["should_continue"],"writes":[],"logic":"根据覆盖度、来源可信度和最大步数决定继续或结束。","control":{"branches":["continue","end"]}},{"id":"official_search","label":"官方来源搜索","subtitle":"Tool Node","kind":"tool","x":500,"y":430,"reads":["tool_name","tool_args"],"writes":["tool_result","messages"],"logic":"限定高校官方域名搜索政策页面和教务处 PDF。"},{"id":"source_validator","label":"来源验证","subtitle":"Function Node","kind":"function","x":760,"y":430,"reads":["tool_result"],"writes":["api_result"],"logic":"检查来源域名、发布日期和政策主体。"},{"id":"brief_formatter","label":"政策简报","subtitle":"LLM Node","kind":"llm","x":760,"y":160,"reads":["messages","draft_answer","api_result"],"writes":["final_answer"],"logic":"在满足覆盖和引用条件后生成结构化简报。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1010,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-react-1","from":"start","to":"react_agent","label":"next","kind":"normal"},{"id":"e-react-2","from":"react_agent","to":"react_route","label":"next","kind":"normal"},{"id":"e-react-3","from":"react_route","to":"official_search","label":"continue","kind":"normal"},{"id":"e-react-4","from":"official_search","to":"source_validator","label":"next","kind":"normal"},{"id":"e-react-5","from":"source_validator","to":"react_agent","label":"next","kind":"normal"},{"id":"e-react-6","from":"react_route","to":"brief_formatter","label":"end","kind":"normal"},{"id":"e-react-7","from":"brief_formatter","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-react-1","react_agent","e-react-2","react_route","e-react-3","official_search","e-react-4","source_validator","e-react-5","react_agent","e-react-2","react_route","e-react-6","brief_formatter","e-react-7","end"],"result":"final_answer: 已完成三所高校政策比较，保留四条官方来源，并记录一次低可信来源被拒绝的观察轨迹。","code":"graph.add_conditional_edges(\n    \"react_agent\",\n    route_action,\n    {\"search\": \"official_search\", \"done\": \"brief_formatter\"}\n)\ngraph.add_edge(\"official_search\", \"source_validator\")\ngraph.add_edge(\"source_validator\", \"react_agent\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('lesson-04-plan', 'Plan-and-Execute · 结构化研究计划', '先生成包含输入、输出和完成条件的计划，再逐项收集资料、抽取政策、比较差异并验证引用。', '{"id":"lesson-04-plan","name":"Plan-and-Execute · 结构化研究计划","description":"先生成包含输入、输出和完成条件的计划，再逐项收集资料、抽取政策、比较差异并验证引用。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"planner","label":"Planner","subtitle":"LLM Node","kind":"llm","x":200,"y":215,"reads":["user_input"],"writes":["messages","draft_answer"],"logic":"把任务拆分为约束识别、资料收集、可信度验证、条款抽取、比较、写作和验收。"},{"id":"plan_review","label":"计划检查","subtitle":"Function Node","kind":"function","x":440,"y":215,"reads":["draft_answer"],"writes":["api_result"],"logic":"检查每一步是否具有输入、输出和完成条件。"},{"id":"executor","label":"Executor","subtitle":"Agent Node","kind":"agent","x":680,"y":215,"reads":["messages","api_result"],"writes":["tool_name","tool_args","tool_result","draft_answer"],"logic":"按计划逐项执行搜索、抽取和比较任务。"},{"id":"completion_check","label":"Completion Check","subtitle":"Function Node","kind":"function","x":920,"y":215,"reads":["draft_answer","tool_result"],"writes":["final_answer"],"logic":"验证三校覆盖、四条引用、风险和三条建议。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1160,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-plan-1","from":"start","to":"planner","label":"next","kind":"normal"},{"id":"e-plan-2","from":"planner","to":"plan_review","label":"next","kind":"normal"},{"id":"e-plan-3","from":"plan_review","to":"executor","label":"next","kind":"normal"},{"id":"e-plan-4","from":"executor","to":"completion_check","label":"next","kind":"normal"},{"id":"e-plan-5","from":"completion_check","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-plan-1","planner","e-plan-2","plan_review","e-plan-3","executor","e-plan-4","completion_check","e-plan-5","end"],"result":"final_answer: 结构化计划的六个步骤已逐项完成，三所高校、四条引用、风险和三条建议均通过检查。","code":"graph.add_edge(START, \"planner\")\ngraph.add_edge(\"planner\", \"plan_review\")\ngraph.add_edge(\"plan_review\", \"executor\")\ngraph.add_edge(\"executor\", \"completion_check\")\ngraph.add_edge(\"completion_check\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('lesson-04-replan', 'Replanning · 失败与目标变化', '当搜索超时、来源缺失或用户追加隐私要求时，保留已完成结果并只修改剩余计划。', '{"id":"lesson-04-replan","name":"Replanning · 失败与目标变化","description":"当搜索超时、来源缺失或用户追加隐私要求时，保留已完成结果并只修改剩余计划。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":260,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"planner","label":"Planner","subtitle":"LLM Node","kind":"llm","x":190,"y":220,"reads":["user_input"],"writes":["messages","draft_answer"],"logic":"生成初始研究计划和验收标准。"},{"id":"executor","label":"Executor","subtitle":"Agent Node","kind":"agent","x":420,"y":220,"reads":["messages","draft_answer"],"writes":["tool_result","api_result","should_continue"],"logic":"执行当前步骤并记录已完成产物。"},{"id":"success_check","label":"步骤成功？","subtitle":"Router Node","kind":"router","x":660,"y":220,"reads":["tool_result","should_continue"],"writes":[],"logic":"区分成功、失败和整体完成。","control":{"branches":["continue","replan","done"]}},{"id":"replanner","label":"Replanner","subtitle":"LLM Node","kind":"llm","x":660,"y":450,"reads":["messages","tool_result","api_result"],"writes":["draft_answer","messages"],"logic":"保留有效结果，为超时、来源缺失或新增隐私要求修改剩余步骤。"},{"id":"final_report","label":"最终简报","subtitle":"Output Node","kind":"output","x":910,"y":160,"reads":["draft_answer","api_result"],"writes":["final_answer"],"logic":"输出更新后的政策比较和建议。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1140,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-replan-1","from":"start","to":"planner","label":"next","kind":"normal"},{"id":"e-replan-2","from":"planner","to":"executor","label":"next","kind":"normal"},{"id":"e-replan-3","from":"executor","to":"success_check","label":"next","kind":"normal"},{"id":"e-replan-4","from":"success_check","to":"executor","label":"continue","kind":"normal"},{"id":"e-replan-5","from":"success_check","to":"replanner","label":"replan","kind":"normal"},{"id":"e-replan-6","from":"replanner","to":"executor","label":"next","kind":"normal"},{"id":"e-replan-7","from":"success_check","to":"final_report","label":"done","kind":"normal"},{"id":"e-replan-8","from":"final_report","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-replan-1","planner","e-replan-2","executor","e-replan-3","success_check","e-replan-5","replanner","e-replan-6","executor","e-replan-3","success_check","e-replan-7","final_report","e-replan-8","end"],"result":"final_answer: 已保留高校 A/B 的结果，为高校 C 使用替代来源，并把新增隐私要求写入剩余计划和最终验收。","code":"graph.add_conditional_edges(\n    \"success_check\",\n    route_result,\n    {\"continue\": \"executor\", \"replan\": \"replanner\", \"done\": \"final_report\"}\n)\ngraph.add_edge(\"replanner\", \"executor\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('lesson-04-evaluator', 'Evaluator-Optimizer · 结构化质量控制', '用覆盖、引用、准确性、风险、字数和建议等结构化 Rubric 控制生成与返工。', '{"id":"lesson-04-evaluator","name":"Evaluator-Optimizer · 结构化质量控制","description":"用覆盖、引用、准确性、风险、字数和建议等结构化 Rubric 控制生成与返工。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":260,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"generator","label":"Generator","subtitle":"LLM Node","kind":"llm","x":200,"y":220,"reads":["user_input"],"writes":["draft_answer"],"logic":"生成包含比较、风险和建议的政策简报初稿。"},{"id":"evaluator","label":"Evaluator","subtitle":"LLM Node","kind":"llm","x":440,"y":220,"reads":["draft_answer"],"writes":["api_result","should_continue"],"logic":"使用结构化 Rubric 输出通过项、失败项和可执行修订建议。"},{"id":"quality_route","label":"通过？","subtitle":"Router Node","kind":"router","x":680,"y":220,"reads":["api_result","should_continue"],"writes":[],"logic":"通过则输出，否则进入优化器。","control":{"branches":["pass","revise"]}},{"id":"optimizer","label":"Optimizer","subtitle":"LLM Node","kind":"llm","x":690,"y":430,"reads":["draft_answer","api_result"],"writes":["draft_answer"],"logic":"根据失败项补齐高校覆盖、引用、隐私风险和可执行建议。"},{"id":"final_output","label":"验收结果","subtitle":"Output Node","kind":"output","x":920,"y":160,"reads":["draft_answer","api_result"],"writes":["final_answer"],"logic":"输出最终简报和验收得分。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1160,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-eval-1","from":"start","to":"generator","label":"next","kind":"normal"},{"id":"e-eval-2","from":"generator","to":"evaluator","label":"next","kind":"normal"},{"id":"e-eval-3","from":"evaluator","to":"quality_route","label":"next","kind":"normal"},{"id":"e-eval-4","from":"quality_route","to":"optimizer","label":"revise","kind":"normal"},{"id":"e-eval-5","from":"optimizer","to":"evaluator","label":"next","kind":"normal"},{"id":"e-eval-6","from":"quality_route","to":"final_output","label":"pass","kind":"normal"},{"id":"e-eval-7","from":"final_output","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-eval-1","generator","e-eval-2","evaluator","e-eval-3","quality_route","e-eval-4","optimizer","e-eval-5","evaluator","e-eval-3","quality_route","e-eval-6","final_output","e-eval-7","end"],"result":"final_answer: 第二轮已满足三校覆盖、四条引用、隐私与公平风险、三条建议和 800-1200 字约束。","code":"graph.add_conditional_edges(\n    \"quality_route\",\n    route_quality,\n    {\"pass\": \"final_output\", \"revise\": \"optimizer\"}\n)\ngraph.add_edge(\"optimizer\", \"evaluator\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('agent-core', '最小 Agent Core', 'START 进入一个处理节点，写入 final_answer 后到 END。', '{"id":"agent-core","name":"最小 Agent Core","description":"START 进入一个处理节点，写入 final_answer 后到 END。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":50,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"process","label":"Function Node","subtitle":"Function Node","kind":"function","x":250,"y":180,"reads":["user_input"],"writes":["final_answer"],"logic":"读取 user_input，生成教学演示结果。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":500,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"process","label":"next","kind":"normal"},{"id":"e2","from":"process","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","process","e2","end"],"result":"final_answer: 已根据 user_input 生成一个可解释的处理结果。","code":"class State(TypedDict):\n    user_input: str\n    final_answer: str\n\ndef process_node(state: State):\n    return {\"final_answer\": \"处理完成\"}\n\ngraph = StateGraph(State)\ngraph.add_node(\"process_node\", process_node)\ngraph.add_edge(START, \"process_node\")\ngraph.add_edge(\"process_node\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('tool-calling-layer', 'Tool Calling Layer', 'Agent 根据 should_continue 决定调用 Tool 或结束。', '{"id":"tool-calling-layer","name":"Tool Calling Layer","description":"Agent 根据 should_continue 决定调用 Tool 或结束。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"agent","label":"Agent Node","subtitle":"Agent 节点 / Agent","kind":"agent","x":190,"y":185,"reads":["user_input","messages","tool_result"],"writes":["messages","should_continue","tool_name","tool_args","final_answer"],"logic":"判断是否需要工具，最多循环 5 次。"},{"id":"tool","label":"Search Tool","subtitle":"Agent 节点 / Tool","kind":"tool","x":405,"y":310,"reads":["tool_call"],"writes":["tool_result","messages"],"logic":"根据 tool_call.query 模拟搜索并写回 tool_result。"},{"id":"observe","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":405,"y":95,"reads":["should_continue"],"writes":[],"logic":"根据 should_continue 控制循环。","control":{"branches":["continue","end"]}},{"id":"end","label":"END","subtitle":"System","kind":"system","x":700,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"agent","label":"next","kind":"normal"},{"id":"e2","from":"agent","to":"observe","label":"next","kind":"normal"},{"id":"e3","from":"observe","to":"tool","label":"continue","kind":"normal"},{"id":"e4","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e5","from":"observe","to":"end","label":"end","kind":"normal"}],"runOrder":["start","e1","agent","e2","tool","e3","observe","e4","agent","e5","end"],"result":"final_answer: Agent 已调用 Search Tool，吸收 Observation 后满足停止条件并结束。","code":"graph.add_node(\"agent\", agent_node)\ngraph.add_node(\"search_tool\", search_tool)\ngraph.add_node(\"observation\", observation_node)\n\ngraph.add_conditional_edges(\n    \"agent\",\n    route_agent,\n    {\"need_tool\": \"search_tool\", \"done\": END}\n)\ngraph.add_edge(\"search_tool\", \"observation\")\ngraph.add_edge(\"observation\", \"agent\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('cited-rag', '带引用的 RAG Pipeline', '多个节点依次读取并更新共享 State。', '{"id":"cited-rag","name":"带引用的 RAG Pipeline","description":"多个节点依次读取并更新共享 State。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":95,"reads":["user_input"],"writes":["messages"],"logic":"接收测试输入并写入消息历史。"},{"id":"read","label":"File Node","subtitle":"File / Cloud Drive Node","kind":"file","x":345,"y":95,"reads":["user_input"],"writes":["tool_result"],"logic":"模拟读取文件内容。"},{"id":"summary","label":"Summary Node","subtitle":"LLM Node","kind":"llm","x":345,"y":305,"reads":["tool_result"],"writes":["final_answer"],"logic":"读取文件内容并生成摘要。"},{"id":"output","label":"Output Node","subtitle":"基础节点 / 输出","kind":"output","x":510,"y":210,"reads":["final_answer"],"writes":["messages"],"logic":"整理最终输出并追加消息。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":720,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"input","label":"next","kind":"normal"},{"id":"e2","from":"input","to":"read","label":"next","kind":"normal"},{"id":"e3","from":"read","to":"summary","label":"next","kind":"normal"},{"id":"e4","from":"summary","to":"output","label":"next","kind":"normal"},{"id":"e5","from":"output","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","input","e2","read","e3","summary","e4","output","e5","end"],"result":"final_answer: 这份文件已经被读取、摘要并整理为教学输出。","code":"graph.add_node(\"input_node\", input_node)\ngraph.add_node(\"read_file_node\", read_file_node)\ngraph.add_node(\"summary_node\", summary_node)\ngraph.add_node(\"output_node\", output_node)\n\ngraph.add_edge(START, \"input_node\")\ngraph.add_edge(\"input_node\", \"read_file_node\")\ngraph.add_edge(\"read_file_node\", \"summary_node\")\ngraph.add_edge(\"summary_node\", \"output_node\")\ngraph.add_edge(\"output_node\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('agent-loop', '有界 Agent Loop', 'Agent 根据 should_continue 决定调用 Tool 或结束。', '{"id":"agent-loop","name":"有界 Agent Loop","description":"Agent 根据 should_continue 决定调用 Tool 或结束。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"agent","label":"Agent Node","subtitle":"Agent 节点 / Agent","kind":"agent","x":190,"y":185,"reads":["user_input","messages","tool_result"],"writes":["messages","should_continue","tool_name","tool_args","final_answer"],"logic":"判断是否需要工具，最多循环 5 次。"},{"id":"tool","label":"Search Tool","subtitle":"Agent 节点 / Tool","kind":"tool","x":405,"y":310,"reads":["tool_call"],"writes":["tool_result","messages"],"logic":"根据 tool_call.query 模拟搜索并写回 tool_result。"},{"id":"observe","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":405,"y":95,"reads":["should_continue"],"writes":[],"logic":"根据 should_continue 控制循环。","control":{"branches":["continue","end"]}},{"id":"end","label":"END","subtitle":"System","kind":"system","x":700,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"agent","label":"next","kind":"normal"},{"id":"e2","from":"agent","to":"observe","label":"next","kind":"normal"},{"id":"e3","from":"observe","to":"tool","label":"continue","kind":"normal"},{"id":"e4","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e5","from":"observe","to":"end","label":"end","kind":"normal"}],"runOrder":["start","e1","agent","e2","tool","e3","observe","e4","agent","e5","end"],"result":"final_answer: Agent 已调用 Search Tool，吸收 Observation 后满足停止条件并结束。","code":"graph.add_node(\"agent\", agent_node)\ngraph.add_node(\"search_tool\", search_tool)\ngraph.add_node(\"observation\", observation_node)\n\ngraph.add_conditional_edges(\n    \"agent\",\n    route_agent,\n    {\"need_tool\": \"search_tool\", \"done\": END}\n)\ngraph.add_edge(\"search_tool\", \"observation\")\ngraph.add_edge(\"observation\", \"agent\")"}');
insert into public.workflow_templates (id, name, description, definition) values ('runtime-recovery', 'Runtime Recovery & Audit', 'Function 写入 task_type，Router 节点决定后续路径。', '{"id":"runtime-recovery","name":"Runtime Recovery & Audit","description":"Function 写入 task_type，Router 节点决定后续路径。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"classify_task","label":"Classify Task","subtitle":"Function Node","kind":"function","x":170,"y":190,"reads":["user_input"],"writes":["task_type"],"logic":"判断用户意图并写入 task_type。"},{"id":"router","label":"Task Router","subtitle":"Router Node","kind":"router","x":360,"y":190,"reads":["task_type"],"writes":[],"logic":"读取 task_type 并映射分支。","control":{"branches":["writing","search"]}},{"id":"summary","label":"Summary Node","subtitle":"LLM Node","kind":"llm","x":560,"y":90,"reads":["user_input","task_type"],"writes":["draft_answer"],"logic":"当 task_type 为 writing 时执行。"},{"id":"search","label":"HTTP API Node","subtitle":"HTTP API Node","kind":"http","x":560,"y":305,"reads":["query","task_type"],"writes":["draft_answer"],"logic":"当 task_type 为 search 时执行。"},{"id":"merge","label":"Format Answer","subtitle":"State Transform Node","kind":"transform","x":760,"y":190,"reads":["draft_answer"],"writes":["final_answer"],"logic":"合并分支输出。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":720,"y":220,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"classify_task","label":"next","kind":"normal"},{"id":"e2","from":"classify_task","to":"router","label":"next","kind":"normal"},{"id":"e3","from":"router","to":"summary","label":"writing","kind":"normal"},{"id":"e4","from":"router","to":"search","label":"search","kind":"normal"},{"id":"e5","from":"summary","to":"merge","label":"next","kind":"normal"},{"id":"e6","from":"search","to":"merge","label":"next","kind":"normal"},{"id":"e7","from":"merge","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","router","e2","summary","e4","merge","e6","end"],"result":"final_answer: Router 判定为 summary，流程进入 Summary Node 并完成输出。","code":"def router(state: State):\n    if \"总结\" in state[\"user_input\"]:\n        return \"summary\"\n    if \"改写\" in state[\"user_input\"]:\n        return \"rewrite\"\n    return \"fallback\"\n\ngraph.add_conditional_edges(\n    \"router_node\",\n    router,\n    {\"summary\": \"summary_node\", \"rewrite\": \"rewrite_node\"}\n)"}');
insert into public.workflow_templates (id, name, description, definition) values ('orchestrator-worker', 'Orchestrator–Worker', '多个节点依次读取并更新共享 State。', '{"id":"orchestrator-worker","name":"Orchestrator–Worker","description":"多个节点依次读取并更新共享 State。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":40,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":95,"reads":["user_input"],"writes":["messages"],"logic":"接收测试输入并写入消息历史。"},{"id":"read","label":"File Node","subtitle":"File / Cloud Drive Node","kind":"file","x":345,"y":95,"reads":["user_input"],"writes":["tool_result"],"logic":"模拟读取文件内容。"},{"id":"summary","label":"Summary Node","subtitle":"LLM Node","kind":"llm","x":345,"y":305,"reads":["tool_result"],"writes":["final_answer"],"logic":"读取文件内容并生成摘要。"},{"id":"output","label":"Output Node","subtitle":"基础节点 / 输出","kind":"output","x":510,"y":210,"reads":["final_answer"],"writes":["messages"],"logic":"整理最终输出并追加消息。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":720,"y":210,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e1","from":"start","to":"input","label":"next","kind":"normal"},{"id":"e2","from":"input","to":"read","label":"next","kind":"normal"},{"id":"e3","from":"read","to":"summary","label":"next","kind":"normal"},{"id":"e4","from":"summary","to":"output","label":"next","kind":"normal"},{"id":"e5","from":"output","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e1","input","e2","read","e3","summary","e4","output","e5","end"],"result":"final_answer: 这份文件已经被读取、摘要并整理为教学输出。","code":"graph.add_node(\"input_node\", input_node)\ngraph.add_node(\"read_file_node\", read_file_node)\ngraph.add_node(\"summary_node\", summary_node)\ngraph.add_node(\"output_node\", output_node)\n\ngraph.add_edge(START, \"input_node\")\ngraph.add_edge(\"input_node\", \"read_file_node\")\ngraph.add_edge(\"read_file_node\", \"summary_node\")\ngraph.add_edge(\"summary_node\", \"output_node\")\ngraph.add_edge(\"output_node\", END)"}');
insert into public.workflow_templates (id, name, description, definition) values ('agentic-workflow', '受治理 Agentic Workflow', '节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。', '{"id":"agentic-workflow","name":"受治理 Agentic Workflow","description":"节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":20,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"normalize_input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":250,"reads":["user_input"],"writes":["query","messages","iteration"],"logic":"清理 user_input，初始化 messages 和 iteration。"},{"id":"classify_task","label":"Classify Task","subtitle":"Function Node","kind":"function","x":355,"y":250,"reads":["user_input"],"writes":["task_type"],"logic":"根据用户输入判断 search / writing / agent / end。"},{"id":"task_router","label":"Task Router","subtitle":"Router Node","kind":"router","x":560,"y":250,"reads":["task_type"],"writes":[],"logic":"读取 task_type，将分支映射到后续节点。","control":{"branches":["search","writing","agent","end"]}},{"id":"call_search_api","label":"HTTP API Node","subtitle":"HTTP API Node","kind":"http","x":790,"y":60,"reads":["query"],"writes":["api_result","draft_answer"],"logic":"通过环境变量配置第三方搜索 API。"},{"id":"write_answer","label":"LLM Node","subtitle":"LLM Node","kind":"llm","x":790,"y":200,"reads":["query"],"writes":["draft_answer"],"logic":"调用大模型生成教学回答草稿。"},{"id":"agent","label":"Agent Node","subtitle":"Agent Node","kind":"agent","x":790,"y":360,"reads":["messages","query","tool_result","iteration"],"writes":["messages","should_continue","tool_name","tool_args","iteration","draft_answer"],"logic":"判断是否继续调用工具。"},{"id":"agent_loop","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":1010,"y":360,"reads":["should_continue"],"writes":[],"logic":"读取 should_continue，决定继续调用工具或退出。","control":{"branches":["continue","end"]}},{"id":"tool","label":"Tool Node","subtitle":"Tool Node","kind":"tool","x":1010,"y":520,"reads":["tool_name","tool_args","messages"],"writes":["tool_result","messages"],"logic":"根据 tool_name 调用内部工具。"},{"id":"format_answer","label":"Format Answer","subtitle":"State Transform Node","kind":"transform","x":1190,"y":200,"reads":["draft_answer"],"writes":["final_answer"],"logic":"将 draft_answer 格式化为 final_answer。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1400,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-start-normalize","from":"start","to":"normalize_input","label":"next","kind":"normal"},{"id":"e-normalize-classify","from":"normalize_input","to":"classify_task","label":"next","kind":"normal"},{"id":"e-classify-router","from":"classify_task","to":"task_router","label":"next","kind":"normal"},{"id":"e-router-search","from":"task_router","to":"call_search_api","label":"search","kind":"normal"},{"id":"e-router-writing","from":"task_router","to":"write_answer","label":"writing","kind":"normal"},{"id":"e-router-agent","from":"task_router","to":"agent","label":"agent","kind":"normal"},{"id":"e-router-end","from":"task_router","to":"end","label":"end","kind":"normal"},{"id":"e-api-format","from":"call_search_api","to":"format_answer","label":"next","kind":"normal"},{"id":"e-llm-format","from":"write_answer","to":"format_answer","label":"next","kind":"normal"},{"id":"e-agent-loop","from":"agent","to":"agent_loop","label":"next","kind":"normal"},{"id":"e-loop-continue","from":"agent_loop","to":"tool","label":"continue","kind":"normal"},{"id":"e-tool-agent","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e-loop-end","from":"agent_loop","to":"format_answer","label":"end","kind":"normal"},{"id":"e-format-end","from":"format_answer","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-start-normalize","normalize_input","e-normalize-classify","classify_task","e-classify-router","task_router","e-router-agent","agent","e-agent-loop","agent_loop","e-loop-continue","tool","e-tool-agent","agent","e-agent-loop","agent_loop","e-loop-end","format_answer","e-format-end","end"],"result":"final_answer: 最终回答：Agent 已调用工具并完成回答。","code":"查看全部代码会展示分文件 LangGraph 原型代码。"}');
insert into public.workflow_templates (id, name, description, definition) values ('multi-agent-workflow', 'Multi-Agent Research System', '继承 Planner、Web Researcher、Paper Researcher 与 Internal RAG；学生调整并行汇合、验证和可靠终止路径。', '{"id":"multi-agent-workflow","name":"Multi-Agent Research System","description":"继承 Planner、Web Researcher、Paper Researcher 与 Internal RAG；学生调整并行汇合、验证和可靠终止路径。","inheritedAssets":["Task Specification","Context Pack","Knowledge & Tool Agent","Runtime + Retry + Checkpoint","Evaluator + Guardrail + Approval"],"reliabilityNotes":["Worker timeout → bounded Retry → Fallback","Verifier rejects → return to Planner","Verified Success → Atomic Settle → Cancel Remaining Workers"],"nodes":[{"id":"start","label":"User Research Question","subtitle":"System","kind":"system","x":20,"y":300,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"planner","label":"Planner","subtitle":"Agent Node","kind":"agent","x":190,"y":300,"reads":[],"writes":[],"logic":"拆分研究问题并分派独立任务。"},{"id":"web","label":"Web Researcher","subtitle":"Agent Node","kind":"agent","x":430,"y":90,"reads":[],"writes":[],"logic":"并行检索 Web；超时后执行有界重试与 fallback。"},{"id":"paper","label":"Paper Researcher","subtitle":"Agent Node","kind":"agent","x":430,"y":290,"reads":[],"writes":[],"logic":"并行检索论文数据库。"},{"id":"rag","label":"Internal RAG","subtitle":"Agent Node","kind":"agent","x":430,"y":490,"reads":[],"writes":[],"logic":"并行查询内部知识库。"},{"id":"merge","label":"Evidence Merge","subtitle":"State Transform","kind":"transform","x":690,"y":290,"reads":[],"writes":[],"logic":"等待并归并 3 个 Worker 的证据。"},{"id":"verifier","label":"Verifier","subtitle":"Evaluator Node","kind":"llm","x":910,"y":290,"reads":[],"writes":[],"logic":"拒绝未验证 Candidate，失败则返回 Planner。"},{"id":"experiment","label":"Experiment Designer","subtitle":"Agent Node","kind":"agent","x":1130,"y":170,"reads":[],"writes":[],"logic":"基于已验证证据设计实验。"},{"id":"critic","label":"Research Critic","subtitle":"Evaluator Node","kind":"llm","x":1130,"y":410,"reads":[],"writes":[],"logic":"批判性检查研究方案。"},{"id":"approval","label":"Human Approval","subtitle":"Human Approval Node","kind":"function","x":1370,"y":290,"reads":[],"writes":[],"logic":"人工批准高风险外发。"},{"id":"settle","label":"Atomic Settle","subtitle":"Function Node","kind":"function","x":1570,"y":290,"reads":[],"writes":[],"logic":"仅在 Verified Success 后原子结算。"},{"id":"cancel","label":"Cancel Remaining Workers","subtitle":"Function Node","kind":"function","x":1770,"y":290,"reads":[],"writes":[],"logic":"结算成功后取消剩余 Worker。"},{"id":"proposal","label":"Final Proposal","subtitle":"Output Node","kind":"output","x":1980,"y":290,"reads":[],"writes":[],"logic":"输出最终立项建议。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":2190,"y":290,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"g1","from":"start","to":"planner","label":"next","kind":"normal"},{"id":"g2","from":"planner","to":"web","label":"parallel","kind":"normal"},{"id":"g3","from":"planner","to":"paper","label":"parallel","kind":"normal"},{"id":"g4","from":"planner","to":"rag","label":"parallel","kind":"normal"},{"id":"g5","from":"web","to":"merge","label":"next","kind":"normal"},{"id":"g6","from":"paper","to":"merge","label":"next","kind":"normal"},{"id":"g7","from":"rag","to":"merge","label":"next","kind":"normal"},{"id":"g8","from":"merge","to":"verifier","label":"next","kind":"normal"},{"id":"g9","from":"verifier","to":"experiment","label":"verified","kind":"normal"},{"id":"g10","from":"verifier","to":"planner","label":"reject / retry","kind":"normal"},{"id":"g11","from":"experiment","to":"critic","label":"next","kind":"normal"},{"id":"g12","from":"critic","to":"approval","label":"next","kind":"normal"},{"id":"g13","from":"approval","to":"settle","label":"approve","kind":"normal"},{"id":"g14","from":"settle","to":"cancel","label":"next","kind":"normal"},{"id":"g15","from":"cancel","to":"proposal","label":"next","kind":"normal"},{"id":"g16","from":"proposal","to":"end","label":"next","kind":"normal"}],"runOrder":["start","g1","planner","g2","web","g3","paper","g4","rag","g5","g6","g7","merge","g8","verifier","g9","experiment","g11","critic","g12","approval","g13","settle","g14","cancel","g15","proposal","g16","end"],"result":"Candidate → Verifier → Verified Success → Atomic Settle → Cancel Remaining Workers → Final Proposal","code":"Golden Demo: timeout / retry / fallback / verifier reject paths are visible on the canvas."}');
insert into public.workflow_templates (id, name, description, definition) values ('agentic-ai-capstone', 'Agentic AI 综合系统', '节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。', '{"id":"agentic-ai-capstone","name":"Agentic AI 综合系统","description":"节点承载逻辑，边只做连接；Router 和 Loop 节点汇总条件编译逻辑。","nodes":[{"id":"start","label":"START","subtitle":"System","kind":"system","x":20,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"},{"id":"normalize_input","label":"Normalize Input","subtitle":"Function Node","kind":"function","x":160,"y":250,"reads":["user_input"],"writes":["query","messages","iteration"],"logic":"清理 user_input，初始化 messages 和 iteration。"},{"id":"classify_task","label":"Classify Task","subtitle":"Function Node","kind":"function","x":355,"y":250,"reads":["user_input"],"writes":["task_type"],"logic":"根据用户输入判断 search / writing / agent / end。"},{"id":"task_router","label":"Task Router","subtitle":"Router Node","kind":"router","x":560,"y":250,"reads":["task_type"],"writes":[],"logic":"读取 task_type，将分支映射到后续节点。","control":{"branches":["search","writing","agent","end"]}},{"id":"call_search_api","label":"HTTP API Node","subtitle":"HTTP API Node","kind":"http","x":790,"y":60,"reads":["query"],"writes":["api_result","draft_answer"],"logic":"通过环境变量配置第三方搜索 API。"},{"id":"write_answer","label":"LLM Node","subtitle":"LLM Node","kind":"llm","x":790,"y":200,"reads":["query"],"writes":["draft_answer"],"logic":"调用大模型生成教学回答草稿。"},{"id":"agent","label":"Agent Node","subtitle":"Agent Node","kind":"agent","x":790,"y":360,"reads":["messages","query","tool_result","iteration"],"writes":["messages","should_continue","tool_name","tool_args","iteration","draft_answer"],"logic":"判断是否继续调用工具。"},{"id":"agent_loop","label":"Agent Loop","subtitle":"Loop Node","kind":"loop","x":1010,"y":360,"reads":["should_continue"],"writes":[],"logic":"读取 should_continue，决定继续调用工具或退出。","control":{"branches":["continue","end"]}},{"id":"tool","label":"Tool Node","subtitle":"Tool Node","kind":"tool","x":1010,"y":520,"reads":["tool_name","tool_args","messages"],"writes":["tool_result","messages"],"logic":"根据 tool_name 调用内部工具。"},{"id":"format_answer","label":"Format Answer","subtitle":"State Transform Node","kind":"transform","x":1190,"y":200,"reads":["draft_answer"],"writes":["final_answer"],"logic":"将 draft_answer 格式化为 final_answer。"},{"id":"end","label":"END","subtitle":"System","kind":"system","x":1400,"y":250,"reads":[],"writes":[],"logic":"工作流系统节点。"}],"edges":[{"id":"e-start-normalize","from":"start","to":"normalize_input","label":"next","kind":"normal"},{"id":"e-normalize-classify","from":"normalize_input","to":"classify_task","label":"next","kind":"normal"},{"id":"e-classify-router","from":"classify_task","to":"task_router","label":"next","kind":"normal"},{"id":"e-router-search","from":"task_router","to":"call_search_api","label":"search","kind":"normal"},{"id":"e-router-writing","from":"task_router","to":"write_answer","label":"writing","kind":"normal"},{"id":"e-router-agent","from":"task_router","to":"agent","label":"agent","kind":"normal"},{"id":"e-router-end","from":"task_router","to":"end","label":"end","kind":"normal"},{"id":"e-api-format","from":"call_search_api","to":"format_answer","label":"next","kind":"normal"},{"id":"e-llm-format","from":"write_answer","to":"format_answer","label":"next","kind":"normal"},{"id":"e-agent-loop","from":"agent","to":"agent_loop","label":"next","kind":"normal"},{"id":"e-loop-continue","from":"agent_loop","to":"tool","label":"continue","kind":"normal"},{"id":"e-tool-agent","from":"tool","to":"agent","label":"next","kind":"normal"},{"id":"e-loop-end","from":"agent_loop","to":"format_answer","label":"end","kind":"normal"},{"id":"e-format-end","from":"format_answer","to":"end","label":"next","kind":"normal"}],"runOrder":["start","e-start-normalize","normalize_input","e-normalize-classify","classify_task","e-classify-router","task_router","e-router-agent","agent","e-agent-loop","agent_loop","e-loop-continue","tool","e-tool-agent","agent","e-agent-loop","agent_loop","e-loop-end","format_answer","e-format-end","end"],"result":"final_answer: 最终回答：Agent 已调用工具并完成回答。","code":"查看全部代码会展示分文件 LangGraph 原型代码。"}');
