insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'agent-workflow-automation-comparison', 0, '比较 Agent、Workflow 与 Automation', '分析三个自动化场景，判断其属于 Agent、Workflow 还是普通 Automation，并解释决策主体与反馈机制。', '["为每个场景判断系统类型","指出决策主体和自主行动边界","说明环境反馈是否改变后续行为","给出不能使用另一类型的理由"]', 'agent-workflow-automation-comparison.md 对比表', '["三个场景分类正确","理由明确且引用自主决策特征","能区分显式流程与环境驱动决策"]', 'instruction', null, 25, '为综合项目确定自动化边界与 Agent 适用范围。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'task-environment-contract', 1, '编写 Agent 任务环境契约', '把一个含糊的研究请求转化为可执行、可验证的任务环境说明。', '["列出可观察状态与允许动作","将用户意图改写为目标","声明资源、时间和安全约束","定义可机器检查的完成条件"]', 'task-environment.yaml', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 30, '作为最终 Agent Core 的任务输入契约。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'agent-architecture-review', 2, '评审经典与 LLM Agent 架构', '针对客服升级场景绘制两种架构并比较其感知、决策、行动与反馈循环。', '["标注经典 Agent 构件","标注模型、上下文、工具、状态和运行时","描述一次完整 Reasoning Loop","给出架构选型结论"]', 'architecture-review.pdf', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 35, '形成综合项目的 Agent Core 架构决策记录。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'lesson-04-direct', 3, 'Direct 基线实验', '一次生成政策简报，记录速度、成本与信息缺口，作为其他推理范式的对照基线。', '["使用给定输入一次生成","记录模型调用与耗时","标注未验证事实和信息缺口"]', 'direct-baseline.md', '["没有隐藏的外部行动","基线指标完整","明确说明 Direct 的适用边界"]', 'instruction', null, 15, null, null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'lesson-04-react', 4, 'ReAct 工具循环', '通过 Reason、Act、Observation 循环完成开放式资料任务，并用停止条件约束执行。', '["每轮说明当前信息缺口","选择并调用适当工具","用 Observation 更新下一步","满足停止条件后结束"]', 'react-trace.json', '["循环结构符合 ReAct","工具结果真实改变后续行动","停止条件可检查"]', 'workflow', 'lesson-04-react', 25, '提供最终 Agent 的交互式推理循环。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'lesson-04-plan', 5, '制定并执行可检查计划', '先生成具有依赖、产物和完成条件的计划，再按顺序执行并记录结果。', '["拆分具有明确产物的步骤","标注步骤依赖","逐步执行并保存结果","核对计划完成状态"]', 'plan-and-execute.json', '["计划覆盖完整目标","依赖顺序有效","每一步结果可核对"]', 'workflow', 'lesson-04-plan', 30, '形成综合项目的 Planning Module 初版。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'lesson-04-replan', 6, '根据新 Observation 修改计划', '在搜索超时或新增隐私要求后，保留已完成步骤并只修改受影响的剩余计划。', '["保留已完成步骤及产物","删除或替换失效步骤","添加新的必要步骤","逐项说明修改理由"]', 'revised-plan.json', '["没有重做有效工作","新计划满足新增约束","每个变更可追溯到 Observation"]', 'workflow', 'lesson-04-replan', 20, '为 Planning Module 增加运行时恢复能力。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'lesson-04-evaluator', 7, '构建输出评估与反思流程', '使用结构化 Rubric 评价输出和执行轨迹，再驱动一次有边界的优化。', '["定义结果与轨迹评价维度","输出逐项 Evaluator 反馈","将反馈转成具体 Reflection","只执行一次有证据的优化"]', 'evaluation-and-revision.json', '["Rubric 可操作","反馈对应真实缺陷","优化结果能说明改进来源"]', 'workflow', 'lesson-04-evaluator', 30, '形成最终系统的 Evaluation Layer。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'human-approval-policy', 8, '设计 Human-in-the-loop 审批策略', '为支付、外发邮件和数据删除三类动作划定人工介入与审批边界。', '["识别风险动作","定义审批触发条件","设计批准、拒绝与超时路径","说明审批上下文"]', 'approval-policy.yaml', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 25, '作为最终 Agent 的高风险动作控制策略。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'minimal-agent-core', 9, '组装最小 Agent Core', '建立具有输入、受控模型调用、运行状态和输出契约的最小可运行 Agent。', '["定义输入边界","配置并调用模型","维护一次运行状态","返回符合契约的输出"]', 'agent-core/', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'agent-core', 45, '构成综合项目的 Agent Core。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'structured-output-contract', 10, '实现结构化输出契约', '为风险分析结果设计 Schema，并验证正确、缺字段和类型错误三组输出。', '["定义字段、类型与嵌套约束","让模型按结构输出","实现 Schema Validation","返回可定位的错误"]', 'risk-report.schema.json + validation-report.md', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 35, '作为最终 Agent 的稳定输出接口。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'context-budget-design', 11, '设计 Context Budget', '在固定上下文预算内选择指令、历史、检索知识、记忆和工具结果。', '["列出候选上下文来源","定义保留和裁剪优先级","处理冲突与过期信息","解释 token 预算分配"]', 'context-budget.md', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 25, '形成 Agent Core 的上下文装配策略。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'tool-calling-layer', 12, '构造 Tool Calling Layer', '从工具定义、选择、参数构造到执行和结果注入，完成一条可审计的工具调用链。', '["定义工具接口与描述","让模型表达 Function Calling 请求","选择工具并校验参数","执行工具并归一化结果","将结果安全注入后续上下文"]', 'tool-layer/', '["接口和参数符合 Schema","选择理由与任务匹配","执行结果可追溯且可被模型消费"]', 'workflow', 'tool-calling-layer', 55, '构成综合项目的 Tool Layer 输入接口与执行主链。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'tool-failure-recovery', 13, '实现工具失败与有界重试', '注入参数错误、超时和临时服务失败，建立分类与有界恢复策略。', '["区分不可重试与可重试失败","设置次数、退避和超时","保留每次失败原因","耗尽预算后安全降级"]', 'tool-retry-policy.ts', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 35, '增强 Tool Layer 的故障恢复能力。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'tool-permission-review', 14, '建立工具权限与审批矩阵', '为读取、写入、外发和删除工具定义最小权限与人工批准规则。', '["列出资源与动作","按风险划分权限","标注必须审批的调用","说明拒绝后的安全行为"]', 'tool-permission-matrix.csv', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 25, '补全 Tool Layer 的权限边界。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'document-ingestion-pipeline', 15, '构建文档摄取管线', '把一份混合格式文档解析、切块并编码为可检索单元。', '["保留标题和来源元数据","制定语义切块策略","生成可比较的 Embedding","抽查边界处信息完整性"]', 'ingestion-manifest.jsonl', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 45, '为最终 Knowledge Layer 准备索引数据。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'cited-rag-pipeline', 16, '实现带引用的检索回答', '完成 Retrieval、Reranking 与 Citation，使回答中的关键结论可追溯。', '["召回候选内容","按任务相关性重排","只用保留候选生成答案","为关键结论附来源引用"]', 'cited-answer.json', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'cited-rag', 50, '构成综合项目的 Knowledge Layer。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'memory-lifecycle-policy', 17, '设计工作状态与长期记忆策略', '区分一次运行的工作状态与跨会话记忆，并制定读取、写入、更新和遗忘规则。', '["划分临时与长期信息","定义记忆写入条件","处理冲突、过期与删除","避免把完整轨迹无选择写入记忆"]', 'memory-policy.md', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 30, '构成综合项目的 Memory Layer。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'bounded-agent-loop', 18, '实现有界 Agent Loop', '将任务生命周期建模为状态机，并为自主循环设置步骤、时间和资源上限。', '["定义 Observe–Think–Act 循环","列出状态和合法转换","设置停止与资源限制","验证超限路径"]', 'agent-runtime.json', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'agent-loop', 45, '形成综合项目的 Runtime 主循环。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'runtime-recovery-audit', 19, '实现 Checkpoint 恢复与审计', '在运行中保存可恢复状态，注入故障后继续执行，并输出完整审计轨迹。', '["保存恢复所需中间状态","从故障点安全继续或降级","记录输入、决策、动作和结果","验证恢复前后结果一致性"]', 'checkpoint + audit-trail.jsonl', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'runtime-recovery', 50, '为 Runtime 增加可靠恢复和审计能力。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'async-tool-execution', 20, '实现异步工具执行', '并发执行两个独立外部工具，同时正确处理超时、取消和结果归并。', '["并发启动独立调用","为调用设置超时","取消后完成资源清理","按输入顺序归一化结果"]', 'async-tool-runner.ts', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 35, '降低 Tool Layer 的端到端等待时间。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'orchestrator-worker-workflow', 21, '构建 Orchestrator–Worker 工作流', '由 Orchestrator 拆分研究任务，多个 Worker 独立执行并返回受约束结果。', '["定义拆分策略","为 Worker 提供最小上下文","约束 Worker 输出","汇总并处理失败子任务"]', 'orchestrator-worker-workflow.json', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'orchestrator-worker', 55, '构成综合项目的并行执行工作流。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'governed-agentic-workflow', 22, '组装受治理 Agentic Workflow', '组合确定性步骤、Agent 决策、评估、重规划和人工审批，完成端到端任务。', '["区分确定性与 Agent 步骤","加入评价和重规划路径","在高风险动作前加入审批","证明每条路径可终止"]', 'governed-workflow.json', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'agentic-workflow', 60, '形成综合项目的主业务编排。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'multi-agent-delegation', 23, '设计 Supervisor 多智能体协作', '让 Supervisor 根据能力边界向专业 Agent 分派任务，并合并带来源的结果。', '["定义各 Agent 职责","选择委派目标","限制传递上下文","处理冲突与失败返回"]', 'delegation-trace.json', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'workflow', 'multi-agent-workflow', 50, '形成综合项目的 Multi-Agent 协作模块。', null, '[]', null);
insert into public.course_assignments (course_id, id, display_order, title, description, requirements, expected_output, acceptance_criteria, mode, workflow_template_id, estimated_minutes, project_contribution, experience, inherited_outputs, dependency_rationale) values ('agentic-ai', 'capability-protocol-map', 24, '绘制 Agent 能力与协议边界图', '比较 Tool、Skill、Plugin、MCP 与 A2A 在能力封装、发现和远程协作中的职责。', '["为五类能力给出接口边界","标注本地与远程调用","区分能力发现与任务委派","为一个场景选择组合方案"]', 'capability-protocol-map.md', '["交付物结构完整且可复核","关键设计决定与课程概念一致","能识别至少一个失败模式并给出处理方式"]', 'instruction', null, 30, '记录综合项目的扩展接口选择。', null, '[]', null);
