insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-parallel-merge', 'parallel-comparison', 2, null, '串行与并行', 'Comparison', '{"table":{"headers":["策略","执行","风险"],"rows":[["串行","Web → Paper → RAG → Merge","等待时间叠加"],["并行","Planner → 3 Workers → Merge","需要处理 partial failure"]]},"visual":"comparison"}');
insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-parallel-merge', 'parallel-flow', 3, null, '并行汇合结构', 'Diagram / Flow', '{"code":"          ┌→ Web ──────┐\nPlanner ──┼→ Paper ────┼→ Evidence Merge\n          └→ RAG ──────┘","visual":"flow"}');
insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-parallel-merge', 'parallel-trace', 4, null, '观察一条真实执行轨迹', 'Trace', '{"code":"Planner start\nWeb start\nPaper start\nRAG start\nRAG finish\nWeb finish\nPaper finish\nMerge received 3/3","visual":"trace"}');
insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-parallel-merge', 'parallel-practice', 5, null, '进入实训', 'Practice CTA', '{"lead":"连接、调整并扩展已加载的并行结构与 Merge。","bullets":["检查 Worker context boundary","定义 Merge 完成条件","保留来源与责任边界"],"visual":"practice"}');
insert into public.materials (course_id, id, lesson_id, display_order, title, description, material_type, storage_path, page_count, duration) values ('agentic-ai', 'native-failure-verification', 'L13', 0, '故障、验证与终止', 'AI Native Lesson · 正确处理 Worker timeout、验证与取消', 'article', null, null, '40 分钟');
insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-failure-verification', 'failure-scenario', 1, null, '第一个 Candidate 不等于成功', 'Warning / Failure Case', '{"lead":"某个 Worker 先返回 Candidate 时立即取消其他 Worker，会把未经验证的候选当成最终事实。","code":"错误：Candidate → Cancel Others","visual":"decision"}');
insert into public.material_segments (course_id, material_id, id, display_order, page, title, section, content) values ('agentic-ai', 'native-failure-verification', 'failure-correct', 2, null, '可靠终止链路', 'Explanation', '{"code":"Candidate → Verifier → Verified Success → Atomic Settle → Cancel Remaining Workers","bullets":["timeout 进入有界 Retry","重试耗尽后进入 Fallback","Verifier reject 返回执行路径"],"visual":"flow"}');
